/// Returns the largest power of two `z` such that `1 ≤ z ≤ n`.
fn largest_power_of_two_le(n: i8) -> i8 {
    // Start with the smallest power of two.
    let mut p: i8 = 1;
    // Double `p` while it's still at most half of `n`.
    // This ensures `2 * p` would not exceed `n` and avoids overflow.
    while p <= n / 2 {
        p *= 2;
    }
    p
}

/// If `n` is odd, returns `(n - 1) / 2`.
/// If `n` is even, finds the largest power of two `z ≤ n` and returns `(n - z) / 2`.
fn solve(n: i8) -> i8 {
    if n % 2 != 0 {
        // n is odd
        (n - 1) / 2
    } else {
        // n is even, compute the largest power of two ≤ n
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

